    this.attachments = const [],
    this.inputHistory = const [],
    this.historyIndex = -1,
    this.historyDraft,
    this.scheduledCount = 0,
    this.scheduledNextDueMs = -1,
    this.jobBoardLines = const [],
    this.subagentBoardRows = const [],
    this.waitingJobs = const [],
