  List<String> sync(List<String> src) {
    if (!_resumable(src) && !_rollbackGrownTail(src)) {
      _rebuild(src);
      return _viewFormatted;
    }
    if (src.length == _through) {
      return _viewFormatted; // nothing new: pure cache hit
