      _lastTailProcessMs = DateTime.now().millisecondsSinceEpoch;
    }
    debugResumedPasses++;
    debugLinesFormatted += src.length - _through;

    final r = _walk(src, from: _through);
    _commitTo(r, src, from: _through);
    _expose(r, src);
    return _viewFormatted;
  }

