  String get _teal => _tealSgr ??= tuiAccentSoftSgr();
  String get _indigo => _indigoSgr ??= tuiAccent2SoftSgr();
  String get _dim => _dimSgr ??= tuiDimSgr();
  String? _tealSgr;
  String? _indigoSgr;

