  /// Opens BSU before the first painted byte of a frame (lazy: idle frames
  /// stay byte-silent, AC — zero-byte static screens).
  void _syncBegin() {
    if (_syncUpdates && !_syncOpen) {
      _output.write('\x1b[?2026h');
      _syncOpen = true;
