      if (cell.attrs != attrs) {
        _output.write(cell.attrs.isEmpty ? '\x1b[0m' : cell.attrs);
        attrs = cell.attrs;
      }
      _output.write(cell.char);
    }
    if (attrs.isNotEmpty) _output.write('\x1b[0m');
    if (hyperlink.isNotEmpty) _output.write('\x1b]8;;\x1b\\');
    _output.write('\x1b[K');
  }
