    return _FramePlan(
      subagents: subagents,
      board: board,
      waiting: waiting,
      scheduled: scheduled,
      chips: chips,
      queue: queueVisible,
      queueHeader: queueHeader,
      queueHint: queueHint,
      sticky: sticky,
      history: consumable + reserve,
      input: inputVisible,
      inputOffset: inputOffset,
    );
