/// A label with NO embedded styling (generic pickers — themes, sessions,
/// settings) is wrapped in the accent directly: the old path returned it
/// untouched, so the selected row was indicated by the one-cell `▸`
/// glyph alone and the label itself rendered in the terminal default —
/// invisible in low-contrast palettes (gh-671 "/theme can't see what is
/// selected").
String _rearmSelection(String label) {
  final theme = FaThemeController.instance;
  final open = theme.accentSgr();
  if (open.isEmpty) return label;
  if (!label.contains('\x1b[0m')) return '$open$label\x1b[0m';
  return label.replaceAll('\x1b[0m', '\x1b[0m$open');
}

/// The [height]-row window of the wrapped output history at [offset].
/// Always paints exactly [height] rows — [height] is the frame plan's
/// [history] (issue #496: the sticky echo's rows left the budget, so
/// window + echo + chrome sums to the physical height exactly).
int _writeHistoryRows(
  StringBuffer b,
  int height,
  List<String> wrapped,
  int offset,
) {
  for (var i = 0; i < height; i++) {
    final row = offset + i;
    b.writeln(row < wrapped.length ? wrapped[row] : '');
  }
  return height;
}

/// The hidden-rows accounting both scroll indicators read (issue #827):
/// [above] counts wrapped rows over the window's top edge (the
/// tail-follow hint names these), [below] the wrapped rows under its
/// bottom edge (the detached percent rule). ONE computation for both
/// directions — the two indicators can never drift apart.
(int above, int below) _foldAccount(List<String> wrapped, int offset) {
  final bottom = _scrollBottom(wrapped);
  return (
    offset.clamp(0, wrapped.length),
    (bottom - offset).clamp(0, wrapped.length),
  );
}

/// Scroll progress indicator — only while the user scrolled away from
/// the live edge (a "you are here" hint); while following, the row stays
/// blank so the layout never shifts. Issue #827 reserved the row and
/// named the hidden rows (`──── ^ N lines above fold - PgUp ────`);
/// gh-1446 retracts the streaming state's TEXT (owner directive: «не
/// надо — просто горизонтальная линия») — the row renders as a plain
/// dim RULE while the tail latch holds and wrapped rows hide above the
/// window. The row reservation, the single [_foldAccount] computation
/// and the detached `── NN% ──` percent all stay.
///
/// Every state embeds into the dim RULE row (the detached percent reads
/// `── NN% ──`): a transcript region is a row stream, and a standalone
/// hint row reads as CONTENT to every screen consumer — the wave-14 PTY
/// resume-equivalence diff treated the padded hint as a transcript row,
/// shifting its tail slice by one (issue #827 wave-14). A textless rule
/// is chrome (`────…`) to every grammar that already strips the
/// separator — and cannot leak counts to shoulder-surfers.
int _writeScrollIndicator(StringBuffer b, List<String> wrapped, int offset) {
  final (above, below) = _foldAccount(wrapped, offset);
  if (followTail && above > 0 && offset < wrapped.length) {
    // A window that shows no rows (zero-height history) announces
    // nothing — the budget rule yields the row, never the prompt row.
    b.writeln(_dim('─' * termWidth));
  } else if (!followTail && below > 0) {
    final bottom = _scrollBottom(wrapped);
    final scrollPercent = bottom == 0
        ? 100
        : ((offset / bottom) * 100).round().clamp(0, 100);
    final progressText = ' $scrollPercent% ';
    // gh-1439: while held with counted arrivals the rule row GROWS the
    // live `● N new` counter plus the one-action re-engage hint (the
    // row itself is a click target — the on-screen jump chip). The
    // position rule stays: the counter extends it, never replaces it.
    // One stripped-width count covers both — the emitted runs carry SGR.
    final counterText = follow.unseen > 0
        ? '· ● ${follow.unseen} new · End = live '
        : '';
    // gh-1439 re-review: one width measure for the combined run — the
    // emission below is ONE styled string, so its width is measured as
    // one string; mixing tuiTextWidth with .length silently relied on
    // every counter char being width-1.
    final progressWidth = tuiTextWidth('$progressText$counterText');
    final leftWidth = (termWidth - progressWidth) ~/ 2;
    final rightWidth = termWidth - progressWidth - leftWidth;
    b.writeln(
      _dim('─' * (leftWidth < 0 ? 0 : leftWidth)) +
          _accent2Plain('$progressText$counterText') +
          _dim('─' * (rightWidth < 0 ? 0 : rightWidth)),
    );
  } else {
    // The row is always reserved (progressH): skipping the blank row
    // while following shifted every later row on scroll.
    b.writeln();
  }
  return 1;
}

/// The busy indicator line (one row): plain-text label + honesty
/// suffixes in FIXED cells (issue #365). gh-1446 strips ALL motion from
/// the row — the kaomoji face (#1374) and the spinner glyph retire, the
/// label starts at column 0 (owner directive: «Working… пусть будет
/// просто текст») and the activity ring lives in the status-line brand
/// zone (AC5). What stays is the #365 no-reflow property: the label
/// zone and the elapsed field hold constant cell counts, so digit
/// growth at a power-of-ten second, the 180 s quiet-threshold crossing
/// and a mid-run phase swap never reflow the row — nothing right of a
/// changing cell moves. The suffixes render provenance-first (a zone
/// that appears or grows must never sit left of a stable one), and the
/// row is fitted AND padded to the terminal width like the status row:
/// stale tails are overwritten and the cursor parks at a stable column.
String _busyRowLine() {
  if (menuOpen && menuModelMode) {
    // An interactive host picker is open: the run is blocked on the
    // user's choice, not working.
