    final wantsAlt = _modes.effectiveAltScreen(view);
    _terminalViewState.beforeScreenChange(_output, wantsAlt);
    if (_modes.apply(_output, view)) {
      _lastLines = const <String>[];
      _lastContent = '';
      _hasRenderedFrame = false;
