      List<List<_Cell>> prev, List<List<_Cell>> next) {
    final rows = prev.length;
    if (rows < 2 || rows != next.length || rows != _maxRows) return null;
    const maxK = 40;
    var best = (matched: -1, k: 0, up: false);
    for (var k = 1; k <= (rows - 1 < maxK ? rows - 1 : maxK); k++) {
