      if (cell.isContinuation) continue;
      if (cell.hyperlink != hyperlink) {
        if (hyperlink.isNotEmpty) _output.write('\x1b]8;;\x1b\\');
        if (cell.hyperlink.isNotEmpty) _output.write(cell.hyperlink);
