  if (assistantMessageEvent is ToolCallStartEvent ||
      assistantMessageEvent is ToolCallEndEvent) {
    _onToolCallGate(assistantMessageEvent);
    return;
  }
  if (assistantMessageEvent is TextDeltaEvent) {
