      return (
        copyWith(
          inputText: '',
          cursor: 0,
          menuOpen: false,
          menuTokenStart: -1,
          attachments: keepAttachments ? null : const [],
        ),
        _submitCmd(text, images),
      );
    }
    final (echoed, echoCut) = _echoAppend(outputLines, inputText);
