      // the landing spot is the live edge — the echo sits at the BOTTOM
      // above the composer, prior history directly above it.
      cleared.copyWith(
        scrollOffset: cleared._followAnchor(cleared._wrappedLines()),
        follow: const FollowMode.live(),
