void main() {
  final src = <String>['echo', 'before'];
  final tx = TranscriptMarkdown(width: 40);
  dump('initial', tx.sync(src), src);

  void step(String note) {
    final out = tx.sync(src);
    final expected = AnsiMarkdown(width: 40).formatAll(src);
    // ignore: avoid_print
    print('== $note');
    // ignore: avoid_print
    print('  through=${tx.debugThroughForTest} boundary=${tx.debugBoundaryFirstForTest}');
    // ignore: avoid_print
    print('  src=$src');
    // ignore: avoid_print
    print('  inc=$out');
    // ignore: avoid_print
    print('  one=$expected');
    // ignore: avoid_print
    print('  match=${out.join('\n') == expected.join('\n')}');
  }

  src.add('| a | b |');
  step('open row1');
  src.add('| 1 | 2 |');
  step('open row2');
  src.add('гарде');
  step('tail');
  src[src.length - 1] = 'гарде2';
  step('tail grew');
  src[src.length - 1] = 'гарде2. Issue';
  step('tail glued');
}

void dump(String tag, List<String> out, List<String> src) {
  // ignore: avoid_print
  print('== $tag out=$out src=$src');
}

