      ),
      isExited: () => false,
      termWidth: 100,
      termHeight: 40,
    );

    (FaTuiModel, Cmd?) pump(FaTuiModel m, Msg msg) {
      final (next, cmd) = m.update(msg);
      return (next as FaTuiModel, cmd);
    }

    // Submit a prompt (echo lands in the transcript).
    for (final ch in 'do the thing'.split('')) {
      final r = pump(model, KeyEvent(key: Key(key: ch)));
      model = r.$1;
    }
    final submit = pump(model, KeyEvent(key: Key(key: '\r')));
    model = submit.$1;

    // Busy on.
    final busy = pump(model, const BusyMsg(true, source: 'run'));
    model = busy.$1;

    // Stream an answer with a table, deltas without newlines.
    final answerLines = [
      '| col1 | col2 |',
      '| --- | --- |',
      '| гарде | 2 |',
      '| b | 3 |',
      '',
      'Issue 1: fixed',
      '2. Issue two remains',
      '3. Issue three tracked',
    ];
    final buffer = StringBuffer();
    for (final line in answerLines) {
      buffer.write('$line\n');
      model = pump(model, OutputMsg(buffer.toString(), newline: true)).$1;
      // Mid-stream service traffic after the table row: a settled job row
      // and a [btw] notice — the ticket's trigger.
      if (line == '| b | 3 |') {
        model = pump(
