  (0x0591, 0x05bd), (0x05c1, 0x05c2),
  (0x0610, 0x061a), (0x064b, 0x065f),
  (0x06d6, 0x06ed),
  (0x0900, 0x0902), (0x0941, 0x0948), (0x0951, 0x0957),
