  // grid to match it (see _detectScrollShift).
  int _maxRows = 0;
  final _cursorState = _CursorRendererState();
  final _terminalViewState = TerminalViewState();

  @override
  void invalidate() {
    _lastGrid = null;
    _lastContent = null;
    _maxRows = 0;
    _cursorState.invalidate();
