/// old code re-measured every token inside flushWord).
final class _WrapState {
  _WrapState(this.width);

  final int width;
  final rows = <String>[];
  final row = StringBuffer();
  final activeSgr = <String>[];
  final wordParts = <_WrapPart>[];
  var wordVisible = 0;
  var col = 0;
