  /// [TranscriptMarkdown]). Same library, so private fields are reachable;
  /// takes copies defensively.
  void restoreState({required bool inFence, required List<String> table}) {
    _inFence = inFence;
    _tableBuffer
      ..clear()
      ..addAll(table);
