/// when the ESC byte does not head one.
int _sgrTokenLength(List<int> units, int i, int n) {
  var k = i + 1;
  if (k >= n || units[k] != 0x5b) return 0;
  k++;
  while (k < n && _isSgrParamByte(units[k])) {
    k++;
