  if (blocks.isEmpty) return null;
  return AssistantMessage(
    content: List.of(blocks),
    api: model.api,
    provider: model.provider,
    model: model.id,
    usage: Usage.zero,
    stopReason: StopReason.stop,
    timestamp: DateTime.now(),
