  if (_fmt.hasPendingTable && pendingStart < 0) pendingStart = i;  // span open from an earlier step
  tableBefore.add(_fmt.hasPendingTable);
  pendingStartAt.add(pendingStart);
  outsPerLine.add(_fmt.consumeLine(src[i]));
  fenceAfter.add(_fmt.inFence);
  if (_fmt.hasPendingTable) {
    if (pendingStart < 0) pendingStart = i;   // THIS step opened the span (buffered its first row)
  } else {
    pendingStart = -1;
    lastClean = ...;
  }
```

