enum MarkdownSurfaceMode {
  /// ANSI-rendered: an interactive terminal with color.
  ansi,

  /// Structure without SGR: a TTY under `NO_COLOR` / `TERM=dumb` — the
  /// same renderer with escapes stripped, layout (bullets, indents, table
