        for (final key in doc.keys) {
          if (!_projectSections.contains('$key')) {
            report.warnings.add(
              ConfigDiagnostic(
                projectConfigPath,
                '"$key" in the project file is dead config — only '
                '${_projectSections.join('/')} are read from here',
              ),
            );
          }
        }
      }
      _collectHostWarnings(doc, projectConfigPath, report.warnings);
    }
    return report;
  }

